// backend/src/core/ai/packages/packages.routes.ts
import { FastifyPluginAsync } from 'fastify';
import type {
  PackageProposeRequest,
  PackageProposeResponse,
  PackageInstallRequest,
  PackageInstallResponse,
} from './packages.types';
import { packagesService } from './packages.service';
import { approvalService } from '../approval/approval.service';

const packagesRoutes: FastifyPluginAsync = async (fastify) => {
  // POST /ai/packages/propose - Propor instalação
  fastify.post<{ Body: PackageProposeRequest }>('/propose', async (req, reply) => {
    if (!req.user || !req.tenant) {
      return reply.status(401).send({ error: 'Não autenticado' });
    }

    const { workspace, packageName, version, reason } = req.body;

    if (!workspace || (workspace !== 'backend' && workspace !== 'frontend')) {
      return reply.status(400).send({ error: 'workspace deve ser "backend" ou "frontend"' });
    }

    if (!packageName || typeof packageName !== 'string') {
      return reply.status(400).send({ error: 'packageName é obrigatório e deve ser uma string' });
    }

    try {
      const response: PackageProposeResponse = packagesService.proposeInstall(
        workspace,
        packageName,
        version,
        reason
      );

      return reply.send(response);
    } catch (error: any) {
      fastify.log.error({ err: error }, 'Erro ao propor instalação');

      if (error.message.includes('inválido') || error.message.includes('bloqueado')) {
        return reply.status(400).send({ error: error.message });
      }

      return reply.status(500).send({ error: 'Erro ao propor instalação' });
    }
  });

  // POST /ai/packages/install - Instalar pacote (requer aprovação)
  fastify.post<{ Body: PackageInstallRequest }>('/install', async (req, reply) => {
    if (!req.user || !req.tenant) {
      return reply.status(401).send({ error: 'Não autenticado' });
    }

    const { approvalToken, workspace, packageName, version } = req.body;

    if (!approvalToken || typeof approvalToken !== 'string') {
      return reply.status(400).send({ error: 'approvalToken é obrigatório' });
    }

    if (!workspace || (workspace !== 'backend' && workspace !== 'frontend')) {
      return reply.status(400).send({ error: 'workspace deve ser "backend" ou "frontend"' });
    }

    if (!packageName || typeof packageName !== 'string') {
      return reply.status(400).send({ error: 'packageName é obrigatório e deve ser uma string' });
    }

    try {
      // Validar token de aprovação
      const approval = approvalService.approve(approvalToken, req.user.id, req.tenant.id);

      if (!approval) {
        return reply.status(403).send({ error: 'Token de aprovação inválido, expirado ou já utilizado' });
      }

      // Verificar se a ação é de instalar pacote
      if (approval.action !== 'install_package' && approval.action !== 'install') {
        return reply.status(403).send({ error: 'Token não autorizado para esta ação' });
      }

      // Verificar se payload corresponde
      if (approval.payload.workspace !== workspace || approval.payload.packageName !== packageName) {
        return reply.status(403).send({ error: 'Token não corresponde aos parâmetros da instalação' });
      }

      // Instalar pacote
      const response: PackageInstallResponse = await packagesService.installPackage(
        workspace,
        packageName,
        version
      );

      return reply.send(response);
    } catch (error: any) {
      fastify.log.error({ err: error }, 'Erro ao instalar pacote');

      if (error.message.includes('inválido') || error.message.includes('bloqueado')) {
        return reply.status(400).send({ error: error.message });
      }

      if (error.message.includes('Timeout')) {
        return reply.status(408).send({ error: error.message });
      }

      return reply.status(500).send({ error: 'Erro ao instalar pacote' });
    }
  });
};

export default packagesRoutes;















